<script>
  /**
   * =============================================================================
   * 📥 LoadingOverlay.vue - 載入覆蓋層組件
   * =============================================================================
   *
   * 用途：顯示全螢幕載入狀態的覆蓋層組件
   *
   * 功能特性：
   * - 🎯 全螢幕覆蓋顯示
   * - ⏳ 支援載入動畫和文字提示
   * - 📊 可選的進度條顯示
   * - 🎨 無障礙設計支援
   * - 📱 響應式設計
   *
   * @author 長期照護資源分析系統團隊
   * @version 2.0.0
   */

  import { computed } from 'vue';

  export default {
    name: 'LoadingOverlay',

    /**
     * =============================================================================
     * 🔧 組件屬性定義 (Component Props Configuration)
     * =============================================================================
     */
    props: {
      /**
       * ⏳ 是否顯示載入覆蓋層
       * @type {boolean}
       */
      isVisible: {
        type: Boolean,
        default: false,
        required: true,
        validator: (value) => typeof value === 'boolean',
      },

      /**
       * 📝 載入過程的主要文字描述
       * @type {string}
       */
      loadingText: {
        type: String,
        default: '載入中...',
        validator: (value) => typeof value === 'string' && value.length > 0,
      },

      /**
       * 📊 載入進度百分比 (0-100，-1 表示不顯示進度)
       * @type {number}
       */
      progress: {
        type: Number,
        default: -1,
        validator: (value) => {
          return typeof value === 'number' && value >= -1 && value <= 100;
        },
      },

      /**
       * 📊 是否顯示進度條
       * @type {boolean}
       */
      showProgress: {
        type: Boolean,
        default: false,
      },

      /**
       * 📝 輔助說明文字 (可選)
       * @type {string}
       */
      subText: {
        type: String,
        default: '',
      },

      /**
       * 🎨 載入覆蓋層主題色彩
       * @type {('primary'|'secondary'|'success'|'warning'|'danger')}
       */
      theme: {
        type: String,
        default: 'primary',
        validator: (value) =>
          ['primary', 'secondary', 'success', 'warning', 'danger'].includes(value),
      },

      /**
       * 📏 載入動畫大小
       * @type {('sm'|'md'|'lg')}
       */
      size: {
        type: String,
        default: 'md',
        validator: (value) => ['sm', 'md', 'lg'].includes(value),
      },
    },

    /**
     * =============================================================================
     * 🔧 組件邏輯設定 (Component Setup)
     * =============================================================================
     */
    setup(props) {
      /**
       * 🎨 動態樣式計算 (Dynamic Style Computation)
       */

      // 載入動畫尺寸映射
      const spinnerSizes = {
        sm: { width: '1.5rem', height: '1.5rem' },
        md: { width: '2rem', height: '2rem' },
        lg: { width: '2.5rem', height: '2.5rem' },
      };

      // 計算載入動畫樣式
      const spinnerStyle = computed(() => ({
        ...spinnerSizes[props.size],
      }));

      // 計算主題CSS類名
      const themeClass = computed(() => `text-${props.theme}`);

      // 進度條樣式類名
      const progressBarClass = computed(() => `bg-${props.theme}`);

      // 格式化進度百分比
      const formattedProgress = computed(() => {
        if (props.progress < 0) return 0;
        return Math.max(0, Math.min(100, Math.round(props.progress)));
      });

      // 是否應該顯示進度條
      const shouldShowProgress = computed(() => {
        return props.showProgress && props.progress >= 0;
      });

      /**
       * 🔧 輔助方法 (Helper Methods)
       */

      // 獲取進度條的 aria-label
      const getProgressAriaLabel = () => {
        return `載入進度 ${formattedProgress.value} 百分比`;
      };

      // 獲取載入狀態的完整描述（用於螢幕閱讀器）
      const getLoadingDescription = () => {
        let description = props.loadingText;
        if (props.subText) {
          description += `，${props.subText}`;
        }
        if (shouldShowProgress.value) {
          description += `，進度 ${formattedProgress.value}%`;
        }
        return description;
      };

      return {
        // 計算屬性
        spinnerStyle,
        themeClass,
        progressBarClass,
        formattedProgress,
        shouldShowProgress,

        // 方法
        getProgressAriaLabel,
        getLoadingDescription,
      };
    },
  };
</script>

<template>
  <!--
    =============================================================================
    ⏳ 載入覆蓋層組件 (Loading Overlay Component)
    =============================================================================

    功能：在資料載入時顯示全螢幕覆蓋層，提供視覺化回饋
    特性：支援無障礙設計、進度條顯示、主題色彩配置
  -->
  <Transition
    name="fade"
    enter-active-class="fade-enter-active"
    leave-active-class="fade-leave-active"
    enter-from-class="fade-enter-from"
    leave-to-class="fade-leave-to"
  >
    <div
      v-if="isVisible"
      class="position-fixed top-0 start-0 w-100 h-100 d-flex align-items-center justify-content-center p-3"
      style="z-index: 9999"
      role="dialog"
      aria-modal="true"
      :aria-label="getLoadingDescription()"
      aria-live="polite"
    >
      <!-- 🌊 背景遮罩層 (Background Overlay) -->
      <div
        class="position-absolute top-0 start-0 w-100 h-100 loading-overlay-backdrop"
        @click.stop
      />

      <!-- 📄 載入內容卡片 (Loading Content Card) -->
      <div
        class="position-relative rounded-3 shadow-lg p-4 text-center loading-overlay-content"
        style="min-width: 300px; max-width: 400px; width: 100%"
      >
        <!-- ⏳ 載入動畫區域 (Loading Animation Section) -->
        <div class="d-flex justify-content-center align-items-center mb-3">
          <div
            class="spinner-border"
            :class="themeClass"
            :style="spinnerStyle"
            role="status"
            aria-hidden="true"
          >
            <!-- 🔍 無障礙輔助文字 (Screen Reader Text) -->
            <span class="visually-hidden">{{ loadingText }}</span>
          </div>
        </div>

        <!-- 📝 主要載入文字區域 (Primary Loading Text Section) -->
        <div class="mb-0">
          <div class="my-title-lg-black mb-2" id="loading-title">
            {{ loadingText }}
          </div>

          <!-- 📝 輔助說明文字 (Secondary Text) -->
          <p v-if="subText" class="my-content-xs-gray mb-0" id="loading-subtitle">
            {{ subText }}
          </p>
        </div>

        <!-- 📊 載入進度條區域 (Loading Progress Section) -->
        <div v-if="shouldShowProgress" class="mt-3">
          <!-- 📊 進度條標籤 (Progress Label) -->
          <div class="d-flex justify-content-between align-items-center mb-2">
            <small class="my-content-xs-gray">載入進度</small>
            <small class="my-content-xs-gray fw-bold">{{ formattedProgress }}%</small>
          </div>

          <!-- 📊 Bootstrap 進度條容器 (Bootstrap Progress Container) -->
          <div
            class="progress"
            role="progressbar"
            :aria-valuenow="formattedProgress"
            :aria-label="getProgressAriaLabel()"
            aria-valuemin="0"
            aria-valuemax="100"
          >
            <!-- 📊 進度條滑塊 (Progress Bar) -->
            <div
              class="progress-bar"
              :class="progressBarClass"
              :style="{ width: formattedProgress + '%' }"
            >
              <span class="visually-hidden">{{ formattedProgress }}% 完成</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </Transition>
</template>

<style scoped>
  /**
 * =============================================================================
 * 🎨 LoadingOverlay 組件樣式 (LoadingOverlay Component Styles)
 * =============================================================================
 */

  /* 🌊 背景遮罩樣式 (Background Overlay Styles) */
  .loading-overlay-backdrop {
    background-color: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
  }

  /* 📄 內容卡片樣式 (Content Card Styles) */
  .loading-overlay-content {
    background-color: var(--my-color-gray-100);
    border: 1px solid var(--my-color-gray-200);
    color: var(--my-color-gray-800);
  }

  /* 🎭 過渡動畫樣式 (Transition Animation Styles) */
  .fade-enter-active,
  .fade-leave-active {
    transition: opacity 0.3s ease;
  }

  .fade-enter-active .loading-overlay-content,
  .fade-leave-active .loading-overlay-content {
    transition: all 0.3s ease;
  }

  .fade-enter-from,
  .fade-leave-to {
    opacity: 0;
  }

  .fade-enter-from .loading-overlay-content,
  .fade-leave-to .loading-overlay-content {
    opacity: 0;
    transform: scale(0.95) translateY(-10px);
  }

  /* 📱 響應式樣式 (Responsive Styles) */
  @media (max-width: 576px) {
    .loading-overlay-content {
      min-width: 280px !important;
      padding: 1.5rem !important;
    }
  }

  @media (max-width: 360px) {
    .loading-overlay-content {
      min-width: 240px !important;
      padding: 1.25rem !important;
    }
  }
</style>
