/**
 * =============================================================================
 * 🗺️ mapDefaults.js - 地圖預設配置常量
 * =============================================================================
 *
 * 用途：統一管理地圖相關的預設值（單一數據源原則）
 *
 * 設計理念：
 * - 📍 集中管理地圖初始狀態
 * - 🔄 避免魔術數字分散在程式碼中
 * - 🎯 提供一致的地圖初始化參數
 * - 📐 支援多種座標格式
 *
 * 使用場景：
 * - MapTab 組件初始化地圖
 * - mapStore 設定預設視圖
 * - 各種地圖相關計算
 *
 * @author 長期照護資源分析系統團隊
 * @version 2.0.0
 */

// =============================================================================
// 📍 地圖中心點配置 (Map Center Configuration)
// =============================================================================

/**
 * 🗺️ 預設地圖中心點座標 - 陣列格式
 *
 * @type {[number, number]}
 * @constant
 * @description
 * - 位置：台灣地理中心（南投縣埔里鎮）
 * - 格式：[緯度, 經度]
 * - 座標系統：WGS84（世界大地測量系統 1984）
 * - 緯度：23.9739° N（北緯）
 * - 經度：120.982° E（東經）
 *
 * @example
 * // 在 Leaflet 中使用
 * map.setView(DEFAULT_MAP_CENTER, 10);
 *
 * @see {@link https://zh.wikipedia.org/wiki/埔里鎮|埔里鎮 - 台灣地理中心}
 */
export const DEFAULT_MAP_CENTER = [23.9739, 120.982];

/**
 * 🗺️ 預設地圖中心點座標 - 物件格式
 *
 * @type {{lat: number, lng: number}}
 * @constant
 * @description
 * - 與 DEFAULT_MAP_CENTER 相同位置，但使用物件格式
 * - 格式：{ lat: 緯度, lng: 經度 }
 * - 適用於需要物件格式的 API 或函數
 *
 * @example
 * // 在某些地圖 API 中使用
 * L.marker([DEFAULT_MAP_CENTER_OBJ.lat, DEFAULT_MAP_CENTER_OBJ.lng]);
 */
export const DEFAULT_MAP_CENTER_OBJ = {
  lat: DEFAULT_MAP_CENTER[0], // 緯度：23.9739° N
  lng: DEFAULT_MAP_CENTER[1], // 經度：120.982° E
};

// =============================================================================
// 🔍 地圖縮放配置 (Map Zoom Configuration)
// =============================================================================

/**
 * 🔍 預設地圖縮放等級
 *
 * @type {number}
 * @constant
 * @default 8
 * @description
 * - 範圍：1-20（Leaflet 標準縮放等級範圍）
 * - 等級 8：適合顯示整個台灣本島的縮放等級
 * - 等級 1：世界級視圖
 * - 等級 20：街道級詳細視圖
 *
 * 縮放等級參考：
 * - 1-3：世界級視圖
 * - 4-6：國家級視圖
 * - 7-9：區域級視圖（台灣全島）
 * - 10-12：城市級視圖
 * - 13-15：街道級視圖
 * - 16-20：建築級視圖
 *
 * @example
 * // 在地圖初始化時使用
 * const map = L.map('map').setView(DEFAULT_MAP_CENTER, DEFAULT_MAP_ZOOM);
 */
export const DEFAULT_MAP_ZOOM = 8;
