<script>
  /**
   * ServiceProviderPicker.vue
   *
   * Purpose:
   * - Provides a dropdown selection interface for service providers
   * - Loads and displays available service providers with statistics
   * - Emits events when service provider is selected
   *
   * Features:
   * - Auto-load service provider list on mount
   * - Display provider ID and service date count
   * - Reactive updates with data store
   */
  import { ref, onMounted, computed } from 'vue';
  import { useDataStore } from '@/stores/dataStore.js';

  export default {
    name: 'ServiceProviderPicker',

    /**
     * 📡 組件事件定義 (Component Events)
     */
    emits: ['provider-selected'],

    /**
     * 🔧 組件設定函數 (Component Setup)
     */
    setup(props, { emit }) {
      // 📦 取得 Pinia 數據存儲實例
      const dataStore = useDataStore();

      // 🔍 本地狀態
      const isLoading = ref(false);
      const error = ref(null);

      // 📊 計算屬性
      const selectedProvider = computed({
        get: () => dataStore.selectedServiceProvider,
        set: (value) => {
          dataStore.setServiceProviderFilter(value);
        },
      });

      const availableProviders = computed(() => dataStore.availableServiceProviders);

      /**
       * 🚀 載入服務人員清單
       */
      const loadProviders = async () => {
        try {
          isLoading.value = true;
          error.value = null;
          await dataStore.loadAvailableServiceProviders();
        } catch (err) {
          error.value = '載入服務人員清單失敗';
          console.error('ServiceProviderPicker: 載入服務人員清單失敗', err);
        } finally {
          isLoading.value = false;
        }
      };

      /**
       * 🎯 處理服務人員選擇
       */
      const handleProviderSelected = async (providerId) => {
        if (providerId) {
          dataStore.setServiceProviderFilter(providerId);
          emit('provider-selected', providerId);
        }
      };

      /**
       * 🚀 組件掛載時載入服務人員清單
       */
      onMounted(async () => {
        await loadProviders();
      });

      // 📊 計算可用服務人員總數
      const totalProvidersCount = computed(() => availableProviders.value.length);

      /**
       * 🎨 獲取服務人員對應的顏色
       */
      const getProviderColor = (providerId) => {
        const color = dataStore.getServiceProviderColor(providerId);
        // 如果是 hex 格式，不能直接用在 CSS class 中，需要返回 null
        // 只有顏色名稱（如 category10-1）才能用在 CSS class
        if (color && color.startsWith('#')) {
          return null; // hex 格式需要用 style 綁定
        }
        return color;
      };

      /**
       * 🎨 獲取服務人員對應的顏色樣式（用於 hex 格式）
       */
      const getProviderColorStyle = (providerId) => {
        const color = dataStore.getServiceProviderColor(providerId);
        if (color && color.startsWith('#')) {
          return { backgroundColor: color };
        }
        return null;
      };

      /**
       * 🏷️ 獲取選中服務人員的標籤
       */
      const getSelectedLabel = computed(() => {
        const provider = availableProviders.value.find((p) => p.id === selectedProvider.value);
        return provider ? `${provider.name} (${provider.dateCount})` : '選擇服務人員';
      });

      // 📤 返回給模板使用
      return {
        selectedProvider,
        availableProviders,
        totalProvidersCount,
        isLoading,
        error,
        handleProviderSelected,
        loadProviders,
        getProviderColor,
        getProviderColorStyle,
        getSelectedLabel,
      };
    },
  };
</script>

<template>
  <div class="service-provider-picker">
    <!-- 載入狀態 -->
    <div v-if="isLoading" class="text-center py-2">
      <div class="spinner-border spinner-border-sm" role="status">
        <span class="visually-hidden">載入中...</span>
      </div>
      <span class="ms-2 my-content-xs-gray">載入服務人員清單...</span>
    </div>

    <!-- 錯誤狀態 -->
    <div v-else-if="error" class="alert alert-warning py-2" role="alert">
      <i class="fas fa-exclamation-triangle me-2"></i>
      {{ error }}
      <button class="btn btn-sm btn-outline-warning ms-2" @click="loadProviders">
        <i class="fas fa-redo"></i> 重試
      </button>
    </div>

    <!-- 選擇器 -->
    <div v-else>
      <div class="dropdown">
        <button
          class="btn btn-sm dropdown-toggle w-100 d-flex align-items-center justify-content-between provider-selector-button"
          type="button"
          data-bs-toggle="dropdown"
          aria-expanded="false"
          :disabled="isLoading"
        >
          <div class="d-flex align-items-center">
            <!-- 顯示選中項目的顏色圓點 -->
            <span
              v-if="getProviderColor(selectedProvider)"
              class="color-dot me-2"
              :class="`my-bgcolor-${getProviderColor(selectedProvider)}`"
            ></span>
            <span
              v-else-if="getProviderColorStyle(selectedProvider)"
              class="color-dot me-2"
              :style="getProviderColorStyle(selectedProvider)"
            ></span>
            <span>{{ getSelectedLabel }}</span>
          </div>
        </button>
        <ul class="dropdown-menu w-100">
          <li v-for="provider in availableProviders" :key="provider.id">
            <a
              class="dropdown-item d-flex align-items-center"
              href="#"
              @click.prevent="handleProviderSelected(provider.id)"
              :class="{ active: selectedProvider === provider.id }"
            >
              <!-- 顏色圓點 -->
              <span
                v-if="getProviderColor(provider.id)"
                class="color-dot me-2"
                :class="`my-bgcolor-${getProviderColor(provider.id)}`"
              ></span>
              <span
                v-else-if="getProviderColorStyle(provider.id)"
                class="color-dot me-2"
                :style="getProviderColorStyle(provider.id)"
              ></span>
              <span v-else class="color-dot-placeholder me-2"></span>
              <span>{{ provider.name }} ({{ provider.dateCount }})</span>
            </a>
          </li>
        </ul>
      </div>
    </div>
  </div>
</template>

