/**
 * =============================================================================
 * 📦 compression.js - 數據壓縮/解壓縮工具模組
 * =============================================================================
 *
 * 用途：提供統一的 Gzip 壓縮和解壓縮功能
 *
 * 主要功能：
 * - 🗜️ Gzip 解壓縮（使用瀏覽器原生 API）
 * - 💾 支援 ArrayBuffer 和 Uint8Array 格式
 * - 🔄 Stream API 處理大型文件
 *
 * @author 長期照護資源分析系統團隊
 * @version 1.0.0
 */

/**
 * 解壓縮 Gzip 壓縮的資料
 *
 * @async
 * @function decompressGzip
 *
 * @description
 * - 優先使用瀏覽器原生的 DecompressionStream API (Chrome 80+, Firefox 113+)
 * - 若瀏覽器不支援，則降級使用 pako 庫
 * - 使用 Streams API 逐塊處理數據，記憶體效率高
 *
 * @param {ArrayBuffer} compressedData - Gzip 壓縮的資料 (ArrayBuffer 格式)
 * @returns {Promise<Uint8Array>} 解壓縮後的資料 (Uint8Array 格式)
 *
 * @throws {Error} 若瀏覽器不支援 DecompressionStream 且未載入 pako 庫
 *
 * @example
 * import { decompressGzip } from '@/utils/compression.js';
 *
 * const response = await fetch('data.json.gz');
 * const compressedData = await response.arrayBuffer();
 * const decompressed = await decompressGzip(compressedData);
 * const jsonText = new TextDecoder('utf-8').decode(decompressed);
 * const jsonData = JSON.parse(jsonText);
 *
 * @notes
 * - DecompressionStream 是現代瀏覽器的標準 API，無需額外依賴
 * - pako 庫僅作為後備方案，通常不需要載入
 * - 使用 Streams API 可以處理大型文件而不會記憶體溢出
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/DecompressionStream
 * @see https://github.com/nodeca/pako - pako 庫文檔
 */
export async function decompressGzip(compressedData) {
  // 使用瀏覽器內建的 DecompressionStream API (現代瀏覽器支援)
  if (typeof DecompressionStream !== 'undefined') {
    const stream = new DecompressionStream('gzip');
    const writer = stream.writable.getWriter();
    const reader = stream.readable.getReader();

    // 寫入壓縮資料
    writer.write(compressedData);
    writer.close();

    // 讀取解壓縮資料
    const chunks = [];
    let done = false;

    while (!done) {
      const { value, done: readerDone } = await reader.read();
      done = readerDone;
      if (value) {
        chunks.push(value);
      }
    }

    // 合併所有 chunks
    const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
    const result = new Uint8Array(totalLength);
    let offset = 0;

    for (const chunk of chunks) {
      result.set(chunk, offset);
      offset += chunk.length;
    }

    return result;
  } else {
    // 如果不支援 DecompressionStream，使用 pako 庫
    // 需要先安裝: npm install pako
    if (typeof window.pako !== 'undefined') {
      return window.pako.inflate(new Uint8Array(compressedData));
    } else {
      throw new Error('瀏覽器不支援 gzip 解壓縮，且未載入 pako 庫');
    }
  }
}
