<script>
  /**
   * FileSelector.vue
   *
   * Purpose:
   * - Provides a dropdown selection interface for data files
   * - Allows filtering data by source file
   * - Emits events when file selection changes
   *
   * Features:
   * - Auto-load file options on mount
   * - Display file names with user-friendly labels
   * - Reactive updates with data store
   */
  import { ref, onMounted, computed } from 'vue';
  import { useDataStore } from '@/stores/dataStore.js';

  export default {
    name: 'FileSelector',

    /**
     * 📡 組件事件定義 (Component Events)
     */
    emits: ['file-selected'],

    /**
     * 🔧 組件設定函數 (Component Setup)
     */
    setup(props, { emit }) {
      // 📦 取得 Pinia 數據存儲實例
      const dataStore = useDataStore();

      // 🔍 本地狀態
      const isLoading = ref(false);
      const error = ref(null);

      // 📊 計算屬性
      const selectedFile = computed({
        get: () => dataStore.selectedFileFilter,
        set: (value) => {
          dataStore.setFileFilter(value);
        },
      });

      // 📁 可用的檔案選項（按新的順序）
      const availableFiles = ref([
        {
          value: 'all',
          label: '全部',
          description: '顯示所有資料來源',
        },
        {
          value: 'filtered_基隆聯祥-20250801-20250831 全部的服務記錄_final.json',
          label: '基隆聯祥',
          description: '基隆聯祥服務記錄',
        },
        {
          value: 'filtered_臺北聯承-20250801-20250831 全部的服務記錄_final.json',
          label: '臺北聯承',
          description: '臺北聯承服務記錄',
        },
        {
          value: 'filtered_三重聯恩-20250801-20250831 全部的服務記錄_final.json',
          label: '三重聯恩',
          description: '三重聯恩服務記錄',
        },
        {
          value: 'filtered_新北聯和-20250801-20250831 全部的服務記錄_final.json',
          label: '新北聯和',
          description: '新北聯和服務記錄',
        },
        {
          value: 'filtered_新北聯宜-20250801-20250831 全部的服務記錄_final.json',
          label: '新北聯宜',
          description: '新北聯宜服務記錄',
        },
        {
          value: 'filtered_新北聯承-20250801-20250831 全部的服務記錄_final.json',
          label: '新北聯承',
          description: '新北聯承服務記錄',
        },
        {
          value: 'filtered_桃園聯承-20250801-20250831 全部的服務記錄_final.json',
          label: '桃園聯承',
          description: '桃園聯承服務記錄',
        },
        {
          value: 'filtered_楊梅聯聚-20250801-20250831 全部的服務記錄_final.json',
          label: '楊梅聯聚',
          description: '楊梅聯聚服務記錄',
        },
        {
          value: 'filtered_新竹聯廣-20250801-20250831 全部的服務記錄_final.json',
          label: '新竹聯廣',
          description: '新竹聯廣服務記錄',
        },
        {
          value: 'filtered_臺中洪幸雪-20250801-20250831 全部的服務記錄_final.json',
          label: '臺中洪幸雪',
          description: '臺中洪幸雪服務記錄',
        },
      ]);

      /**
       * 🎯 處理檔案選擇
       */
      const handleFileSelected = async (fileName) => {
        if (fileName) {
          dataStore.setFileFilter(fileName);
          emit('file-selected', fileName);
        }
      };

      /**
       * 🚀 組件掛載時初始化
       */
      onMounted(async () => {
        // 檔案選項已經在 computed 中定義，無需額外載入
      });

      /**
       * 🎨 獲取檔案對應的顏色
       */
      const getFileColor = (fileName) => {
        return dataStore.getFileColor(fileName);
      };

      /**
       * 🏷️ 獲取選中檔案的標籤
       */
      const getSelectedLabel = computed(() => {
        const file = availableFiles.value.find((f) => f.value === selectedFile.value);
        return file ? file.label : '選擇資料來源';
      });

      // 📤 返回給模板使用
      return {
        selectedFile,
        availableFiles,
        isLoading,
        error,
        handleFileSelected,
        getFileColor,
        getSelectedLabel,
      };
    },
  };
</script>

<template>
  <div class="file-selector">
    <!-- 載入狀態 -->
    <div v-if="isLoading" class="text-center py-2">
      <div class="spinner-border spinner-border-sm" role="status">
        <span class="visually-hidden">載入中...</span>
      </div>
      <span class="ms-2 my-content-xs-gray">載入檔案選項...</span>
    </div>

    <!-- 錯誤狀態 -->
    <div v-else-if="error" class="alert alert-warning py-2" role="alert">
      <i class="fas fa-exclamation-triangle me-2"></i>
      {{ error }}
    </div>

    <!-- 選擇器 -->
    <div v-else>
      <div class="dropdown">
        <button
          class="btn btn-sm dropdown-toggle w-100 d-flex align-items-center justify-content-between file-selector-button"
          type="button"
          data-bs-toggle="dropdown"
          aria-expanded="false"
          :disabled="isLoading"
        >
          <div class="d-flex align-items-center">
            <!-- 顯示選中項目的顏色圓點 -->
            <span
              v-if="getFileColor(selectedFile)"
              class="color-dot me-2"
              :class="`my-bgcolor-${getFileColor(selectedFile)}`"
            ></span>
            <span>{{ getSelectedLabel }}</span>
          </div>
        </button>
        <ul class="dropdown-menu w-100">
          <li v-for="file in availableFiles" :key="file.value">
            <a
              class="dropdown-item d-flex align-items-center"
              href="#"
              @click.prevent="handleFileSelected(file.value)"
              :class="{ active: selectedFile === file.value }"
            >
              <!-- 顏色圓點 -->
              <span
                v-if="getFileColor(file.value)"
                class="color-dot me-2"
                :class="`my-bgcolor-${getFileColor(file.value)}`"
              ></span>
              <span v-else class="color-dot-placeholder me-2"></span>
              <span>{{ file.label }}</span>
            </a>
          </li>
        </ul>
      </div>
    </div>
  </div>
</template>

