  }

  .file-selector-button:focus {
    border-color: var(--my-color-blue);
    box-shadow: 0 0 0 0.2rem rgba(0, 123, 255, 0.25);
  }

  .file-selector-button:disabled {
    background-color: var(--my-color-gray-100);
