/**
 * 全局數據緩存
 * 用於存储已加載的 JSON 文件數據，避免重複讀取
 * 這是整個應用程式共享的單一緩存實例
 * @type {Array|null}
 */
let cachedAllData = null;

/**
 * 數據載入狀態
 * @type {boolean}
 */
let isDataLoading = false;

/**
 * 數據載入 Promise（用於避免並發載入）
 * @type {Promise|null}
 */
let dataLoadingPromise = null;

/**
 * 清除緩存數據（用於開發或需要重新載入數據的情況）
 * @function clearDataCache
 */
export function clearDataCache() {
  cachedAllData = null;
  isDataLoading = false;
  dataLoadingPromise = null;
  // eslint-disable-next-line no-console
  console.log('🗑️ [dataProcessor] 數據緩存已清除');
}

