// 📥 數據載入和合併函數
// =============================================================================

/**
 * 載入並合併多個 JSON 文件（帶緩存機制）
 *
 * @async
 * @function loadAndMergeJsonFiles
 * @export
 *
 * @description
 * - 優先嘗試載入 .gz 壓縮文件，節省網路傳輸時間
 * - 若壓縮文件不存在，則降級為載入原始 JSON 文件
 * - 使用瀏覽器原生 DecompressionStream API 進行 gzip 解壓縮
 * - 為每條記錄添加 `filename` 欄位，方便後續追蹤數據來源
 * - 數據只會載入一次，後續調用直接返回緩存的數據
 *
 * @param {Array<string>} fileNames - 要載入的 JSON 文件名列表（不含 .gz 副檔名）
 * @returns {Promise<Array<Object>>} 合併後的數據陣列
 *
 * @throws {Error} 載入或解析失敗時拋出錯誤
 *
 * @example
 * import { loadAndMergeJsonFiles } from '@/utils/dataProcessor.js';
 *
 * const fileNames = [
 *   'filtered_臺中洪幸雪-20250801-20250831 全部的服務記錄_final.json',
 *   'filtered_基隆聯祥-20250801-20250831 全部的服務記錄_final.json'
 * ];
 * const allData = await loadAndMergeJsonFiles(fileNames);
 *
 * @notes
 * - 文件路徑基於 `/long-term-care-web-taichung/data/json/` 目錄
 * - 支援 GitHub Pages 部署時的路徑解析
 * - 載入失敗時會中斷並拋出錯誤，確保數據完整性
 * - 數據會被緩存，只在首次調用時載入，提高性能
 * - 此函數被導出供其他模組使用，確保整個應用程式共享同一緩存
 */
export async function loadAndMergeJsonFiles(fileNames) {
  // 如果數據已經緩存，直接返回
  if (cachedAllData !== null) {
    // eslint-disable-next-line no-console
    console.log('🚀 [dataProcessor] 使用緩存的數據，無需重新載入');
    return cachedAllData;
  }

  // 如果正在載入中，等待載入完成
  if (isDataLoading && dataLoadingPromise) {
    // eslint-disable-next-line no-console
    console.log('⏳ [dataProcessor] 數據正在載入中，等待完成...');
    return await dataLoadingPromise;
  }

  // 開始載入數據
  isDataLoading = true;
  dataLoadingPromise = (async () => {
    const allData = [];

    // eslint-disable-next-line no-console
    console.log('📥 [dataProcessor] 開始載入 JSON 數據（首次載入）...');

    for (const fileName of fileNames) {
      try {
        // 優先嘗試載入壓縮檔案 (.gz)
        let filePath = `/long-term-care-web-taichung/data/json/${fileName}.gz`;
        let response = await fetch(filePath);

        // 如果壓縮檔案不存在，則嘗試載入原始檔案
        if (!response.ok) {
          // eslint-disable-next-line no-console
          console.log(`壓縮檔案不存在，嘗試載入原始檔案: ${fileName}`);
          filePath = `/long-term-care-web-taichung/data/json/${fileName}`;
          response = await fetch(filePath);
        }

        if (!response.ok) {
          // eslint-disable-next-line no-console
          console.error('HTTP 錯誤:', {
            status: response.status,
            statusText: response.statusText,
            url: response.url,
          });
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        let jsonData;

        // 檢查是否為壓縮檔案
        if (filePath.endsWith('.gz')) {
          // 載入壓縮檔案並解壓縮
          const compressedData = await response.arrayBuffer();
          const decompressedData = await decompressGzip(compressedData);
          const jsonText = new TextDecoder('utf-8').decode(decompressedData);
          jsonData = JSON.parse(jsonText);
          // eslint-disable-next-line no-console
          console.log(`✅ 成功載入壓縮檔案: ${fileName}.gz`);
        } else {
          // 載入原始 JSON 檔案
          jsonData = await response.json();
          // eslint-disable-next-line no-console
          console.log(`✅ 成功載入原始檔案: ${fileName}`);
        }

        // 為每個記錄添加filename欄位
        const dataWithFilename = jsonData.map((record) => ({
          ...record,
          filename: fileName,
        }));

        allData.push(...dataWithFilename);
      } catch (error) {
        // eslint-disable-next-line no-console
        console.error(`❌ 載入文件 ${fileName} 失敗:`, error);
        throw error;
      }
    }

    // 緩存數據
    cachedAllData = allData;
    isDataLoading = false;
    dataLoadingPromise = null;

    // eslint-disable-next-line no-console
    console.log(`✅ [dataProcessor] 數據載入完成並已緩存，共 ${allData.length} 筆記錄`);

    return allData;
  })();

  return await dataLoadingPromise;
}

