/**
 * =============================================================================
 * 🗺️ mapStore.js - 地圖與面板狀態管理中心
 * =============================================================================
 *
 * 用途：使用 Pinia 進行地圖狀態和響應式面板佈局的集中化管理
 *
 * 主要功能：
 * - 🗺️ 地圖視圖狀態管理（縮放等級、中心點座標）
 * - 📐 響應式面板尺寸管理（左側、右側、底部面板）
 * - 🎨 地圖圖層引用管理
 * - 📊 窗口尺寸追蹤
 *
 * 技術特性：
 * - 🔄 響應式狀態更新
 * - 📏 自動計算面板尺寸
 * - 🎯 單一數據源原則
 *
 * @author 長期照護資源分析系統團隊
 * @version 2.0.0
 */

// 🔧 Vue Composition API 引入
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import { DEFAULT_MAP_CENTER, DEFAULT_MAP_ZOOM } from '@/config/mapDefaults';

/**
 * 🗺️ 地圖與面板存儲定義 (Map and Panel Store Definition)
 *
 * 此 Store 負責：
 * 1. 管理地圖的視圖狀態（中心點、縮放等級）
 * 2. 追蹤響應式面板的尺寸
 * 3. 儲存地圖圖層的引用
 * 4. 提供視窗尺寸資訊
 */
export const useMapStore = defineStore('map', () => {
  // =============================================================================
  // 📐 面板尺寸狀態 (Panel Size States)
  // =============================================================================

  /**
   * 🔲 左側面板寬度（像素）
   * @type {Ref<number>}
   * @default 300
   */
  const leftViewWidth = ref(300);

  /**
   * 🔲 右側面板寬度（像素）
   * @type {Ref<number>}
   * @default 300
   */
  const rightViewWidth = ref(300);

  /**
   * 🔲 底部面板高度（像素）
   * @type {Ref<number>}
   * @default 250
   */
  const bottomViewHeight = ref(250);

  /**
   * 🖥️ 瀏覽器視窗寬度（像素）
   * @type {Ref<number>}
   * @description 用於響應式佈局計算，需要在 resize 事件中更新
   */
  const windowWidth = ref(window.innerWidth);

  /**
   * 🖥️ 瀏覽器視窗高度（像素）
   * @type {Ref<number>}
   * @description 用於響應式佈局計算，需要在 resize 事件中更新
   */
  const windowHeight = ref(window.innerHeight);

  // =============================================================================
  // 🗺️ 地圖視圖狀態 (Map View States)
  // =============================================================================

  /**
   * 🔍 地圖縮放等級
   * @type {Ref<number>}
   * @default DEFAULT_MAP_ZOOM (預設為 8)
   * @description
   * - 範圍：1-20
   * - 值越大表示縮放越大（地圖越詳細）
   * - 由 MapTab 組件更新
   */
  const zoomLevel = ref(DEFAULT_MAP_ZOOM);

  /**
   * 📍 地圖中心點座標
   * @type {Ref<{lat: number, lng: number}>}
   * @default { lat: DEFAULT_MAP_CENTER[0], lng: DEFAULT_MAP_CENTER[1] }
   * @description
   * - 使用 WGS84 座標系統
   * - lat: 緯度（-90 到 90）
   * - lng: 經度（-180 到 180）
   * - 預設為台灣地理中心（南投埔里）
   */
  const currentCoords = ref({
    lat: DEFAULT_MAP_CENTER[0],
    lng: DEFAULT_MAP_CENTER[1],
  });

  // =============================================================================
  // 🎨 地圖圖層引用狀態 (Map Layers Reference States)
  // =============================================================================

  /**
   * 🗺️ 地圖圖層物件集合
   * @type {Ref<Object>}
   * @property {Object|null} geojsonLayer - GeoJSON 圖層實例
   * @property {Object|null} pointLayer - 點圖層實例
   * @property {Object|null} heatmapLayer - 熱力圖圖層實例
   * @property {Object|null} clusterLayer - 聚合圖層實例
   * @property {Object|null} bufferLayer - 緩衝區圖層實例
   * @description
   * - 儲存各類型圖層的 Leaflet 圖層物件引用
   * - null 表示該圖層尚未建立或已被移除
   * - 用於圖層管理和控制
   */
  const mapLayers = ref({
    geojsonLayer: null, // GeoJSON 向量圖層
    pointLayer: null, // 點位圖層
    heatmapLayer: null, // 熱力圖圖層
    clusterLayer: null, // 點位聚合圖層
    bufferLayer: null, // 緩衝區分析圖層
  });

  // =============================================================================
  // 🧮 計算屬性 (Computed Properties)
  // =============================================================================

  /**
   * 📏 計算主要面板寬度
   * @returns {number} 主面板寬度（像素）
   * @description
   * - 計算公式：總寬度 - 左側面板寬度 - 右側面板寬度
   * - 最小寬度：200px（確保基本可用性）
   * - 用於響應式佈局中的中間主要內容區域
   */
  const mainPanelWidth = computed(() => {
    const availableWidth = windowWidth.value - leftViewWidth.value - rightViewWidth.value;
    return Math.max(200, availableWidth); // 確保最小寬度 200px
  });

  // =============================================================================
  // 🔧 方法定義區 (Methods Section)
  // =============================================================================

  // 注意：目前此 Store 採用直接狀態更新模式
  // 如需添加複雜的狀態更新邏輯，可在此區域定義方法
  // 例如：
  // const updateMapView = (center, zoom) => { ... }
  // const resetPanelSizes = () => { ... }

  // =============================================================================
  // 📤 返回公開介面 (Return Public Interface)
  // =============================================================================

  /**
   * 導出 Store 的公開介面
   *
   * 包含：
   * - 所有響應式狀態（可讀可寫）
   * - 計算屬性（只讀）
   * - 公開方法（如有定義）
   */
  return {
    // 📐 面板尺寸狀態
    leftViewWidth, // 左側面板寬度
    rightViewWidth, // 右側面板寬度
    bottomViewHeight, // 底部面板高度
    windowWidth, // 視窗寬度
    windowHeight, // 視窗高度

    // 🗺️ 地圖狀態
    zoomLevel, // 縮放等級
    currentCoords, // 中心座標
    mapLayers, // 圖層引用集合

    // 🧮 計算屬性
    mainPanelWidth, // 主面板寬度（計算得出）
  };
});
