<script>
  /**
   * =============================================================================
   * 📝 DetailItem.vue - 詳細資訊項目展示組件
   * =============================================================================
   *
   * 用途：以標籤-值對的形式展示單一屬性資訊
   *
   * 功能特性：
   * - 📊 標籤-值對展示（Label-Value Pair Display）
   * - 🎨 統一的視覺樣式（Consistent Visual Style）
   * - 🔄 支援多種資料類型（Supports Multiple Data Types）
   * - 📱 響應式設計（Responsive Design）
   * - 🔡 自動換行處理（Automatic Text Wrapping）
   *
   * 使用場景：
   * - PropertiesTab 右側屬性面板顯示
   * - 服務人員詳細資訊展示
   * - 地圖物件屬性列表
   * - 任何需要標籤-值對展示的場合
   *
   * @author 長期照護資源分析系統團隊
   * @version 2.0.0
   */

  export default {
    name: 'DetailItem',

    /**
     * =============================================================================
     * 🔧 組件屬性定義 (Component Props Definition)
     * =============================================================================
     */
    props: {
      /**
       * 📋 標籤文字
       * @type {String}
       * @required
       * @description
       * - 顯示在上方的標籤文字（通常為屬性名稱）
       * - 樣式：灰色、小字體（my-title-xs-gray）
       * - 用途：標識下方值的意義
       *
       * @example
       * <DetailItem label="姓名" value="張三" />
       */
      label: {
        type: String,
        required: true,
      },

      /**
       * 📊 值內容
       * @type {String|Number|Boolean|Object}
       * @required
       * @description
       * - 顯示在下方的值內容
       * - 樣式：黑色、中字體（my-content-sm-black）
       * - 支援多種資料類型
       * - 物件類型會自動轉換為字串顯示
       *
       * @example
       * <DetailItem label="年齡" :value="25" />
       * <DetailItem label="地址" value="台北市信義區..." />
       * <DetailItem label="狀態" :value="true" />
       */
      value: {
        type: [String, Number, Boolean, Object],
        required: true,
      },
    },
  };
</script>

<template>
  <!--
    =============================================================================
    📝 詳細資訊項目組件 (Detail Item Component)
    =============================================================================

    展示格式：
    ┌─────────────────┐
    │ 標籤 (灰色小字)  │
    │ 值 (黑色中字)    │
    └─────────────────┘

    使用範例：
    <DetailItem label="姓名" value="張三" />
    <DetailItem label="年齡" :value="25" />
  -->
  <div class="pb-2">
    <!-- 📋 標籤區域 (Label Section) -->
    <!-- 顯示屬性名稱，使用統一的標題樣式 -->
    <div class="my-title-xs-gray pb-1">{{ label }}</div>

    <!-- 📊 值區域 (Value Section) -->
    <!-- 顯示屬性值，使用統一的內容樣式 -->
    <div class="my-content-sm-black pb-1">{{ value }}</div>
  </div>
</template>

<style scoped>
  /**
   * =============================================================================
   * 🎨 DetailItem 組件樣式 (DetailItem Component Styles)
   * =============================================================================
   */

  /**
   * 📝 文字換行處理 (Text Wrapping)
   * @description 確保長文字能夠自動換行，避免破壞佈局
   */
  .lead {
    word-wrap: break-word; /* 允許在單字內部換行 */
  }

  /**
   * 🔧 中間調整器樣式 (Middle Resizer Styles)
   * @description 垂直拖曳調整器的視覺樣式
   * @note 這個樣式似乎與 DetailItem 無關，可能是誤置的樣式
   */
  .my-resizer-middle {
    background-color: white; /* 背景色：白色 */
    position: relative; /* 定位模式：相對定位 */
    border-top: 1px solid var(--my-color-gray-200); /* 上邊框：淺灰色分隔線 */
    border-bottom: 1px solid var(--my-color-gray-200); /* 下邊框：淺灰色分隔線 */
  }
</style>
